#!/usr/bin/env python3
import sys
from html.parser import HTMLParser

class XSSFilter(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.result = []
        self.in_script = False

    def handle_starttag(self, tag, attrs):
        if tag.lower() == 'script':
            self.in_script = True
            return

        # Filter out event handlers and javascript: URLs
        clean_attrs = []
        for name, value in attrs:
            name_lower = name.lower()
            # Skip event handlers (on*)
            if name_lower.startswith('on'):
                continue
            # Skip javascript: URLs
            if value and name_lower in ('href', 'src', 'action', 'formaction', 'data', 'poster', 'background', 'dynsrc', 'lowsrc'):
                if value.strip().lower().startswith('javascript:'):
                    continue
            clean_attrs.append((name, value))

        # Reconstruct the tag
        if clean_attrs:
            attrs_str = ''
            for name, value in clean_attrs:
                if value is None:
                    attrs_str += f' {name}'
                elif '"' in value and "'" not in value:
                    attrs_str += f" {name}='{value}'"
                else:
                    attrs_str += f' {name}="{value}"'
            self.result.append(f'<{tag}{attrs_str}>')
        else:
            self.result.append(f'<{tag}>')

    def handle_endtag(self, tag):
        if tag.lower() == 'script':
            self.in_script = False
            return
        self.result.append(f'</{tag}>')

    def handle_startendtag(self, tag, attrs):
        if tag.lower() == 'script':
            return
        # Use handle_starttag logic for attrs
        clean_attrs = []
        for name, value in attrs:
            name_lower = name.lower()
            if name_lower.startswith('on'):
                continue
            if value and name_lower in ('href', 'src', 'action', 'formaction', 'data', 'poster', 'background', 'dynsrc', 'lowsrc'):
                if value.strip().lower().startswith('javascript:'):
                    continue
            clean_attrs.append((name, value))

        if clean_attrs:
            attrs_str = ''
            for name, value in clean_attrs:
                if value is None:
                    attrs_str += f' {name}'
                elif '"' in value and "'" not in value:
                    attrs_str += f" {name}='{value}'"
                else:
                    attrs_str += f' {name}="{value}"'
            self.result.append(f'<{tag}{attrs_str}/>')
        else:
            self.result.append(f'<{tag}/>')

    def handle_data(self, data):
        if not self.in_script:
            self.result.append(data)

    def handle_comment(self, data):
        self.result.append(f'<!--{data}-->')

    def handle_decl(self, decl):
        self.result.append(f'<!{decl}>')

    def handle_pi(self, data):
        self.result.append(f'<?{data}>')

    def unknown_decl(self, data):
        self.result.append(f'<![{data}]>')

    def get_result(self):
        return ''.join(self.result)

def main():
    if len(sys.argv) != 2:
        print("Usage: python filter.py <html_file>", file=sys.stderr)
        sys.exit(1)

    filepath = sys.argv[1]

    with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
        html_content = f.read()

    parser = XSSFilter()
    parser.feed(html_content)
    result = parser.get_result()

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(result)

if __name__ == '__main__':
    main()
EOF
